def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0

    if not alive:
        return min(budget, 18)

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    total_alive = len(alive)

    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opponents += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid')))
            except Exception:
                pass

    units = supply / WATER_REQ
    scarcity = total_alive - units

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / len(prev_bids)
    else:
        highest_prev = 0
        avg_prev = 0

    if hp <= 2 or no_water >= 2:
        bid = max(60, highest_prev + 3)
    elif hp <= 4 or no_water >= 1:
        bid = max(48, avg_prev + 4, highest_prev * 0.9)
    else:
        if scarcity <= 0:
            bid = max(16, avg_prev * 0.6)
        elif scarcity <= 1:
            bid = max(28, avg_prev + 2)
        else:
            bid = max(36, highest_prev + 2)

    if urgent_opponents >= max(1, total_alive // 2):
        bid += 5
    if rich_opponents >= max(1, total_alive // 2):
        bid += 4

    if highest_prev >= 60 and hp > 4 and no_water == 0:
        bid = min(bid, 32)

    reserve = 0
    if hp <= 3:
        reserve = 0
    elif hp <= 5:
        reserve = 20
    else:
        reserve = 35

    affordable = max(0, budget - reserve)
    if affordable <= 0:
        affordable = min(budget, 12 if hp > 3 else budget)

    bid = min(bid, affordable)
    bid = min(bid, budget)
    if bid < 0:
        bid = 0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    # Agent Constants
    WATER_REQ = 9
    DAILY_SALARY = 90

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    num_alive_opponents = len(alive_opponents)

    # Calculate available water units based on my requirement
    # CRITICAL: Ensure int() cast for any list indexing or integer-like operations
    available_water_slots = int(day_context['supply'] // WATER_REQ)

    # Base bid amount for general scenarios
    base_bid = DAILY_SALARY * 0.5

    # Strategy 1: No opponents left, bid low to save budget
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)

    # Strategy 2: High desperation (low HP or consecutive no-water days)
    # If HP is very low or I've missed water multiple days, bid very aggressively.
    if my_status['hp'] <= 2 or my_status['no_water_days'] >= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    # Strategy 3: Analyze opponent's previous bids from 'previous_trace'
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)
        avg_prev_bid = sum(yesterday_bids) / len(yesterday_bids)

        # Case A: Opponents were very aggressive yesterday
        if highest_prev_bid >= DAILY_SALARY * 0.8:
            if my_status['hp'] > 3: # If healthy, let them overspend, bid low to save
                return min(my_status['budget'], DAILY_SALARY * 0.35)
            else: # If not healthy, need to compete, bid slightly above their high bid
                return min(my_status['budget'], highest_prev_bid + 5)

        # Case B: Opponents were moderately aggressive
        elif highest_prev_bid >= DAILY_SALARY * 0.6:
            # If supply is tight (not enough slots for everyone), be more aggressive
            if available_water_slots <= num_alive_opponents + 1:
                return min(my_status['budget'], highest_prev_bid + 3)
            else: # Supply is okay, bid just above to win
                return min(my_status['budget'], max(base_bid, highest_prev_bid + 1))

        # Case C: Opponents were generally conservative
        else:
            # Bid slightly above average or highest conservative bid, but ensure I get water
            # Consider supply here too
            if available_water_slots <= num_alive_opponents + 1: # Tight supply
                 return min(my_status['budget'], max(base_bid, highest_prev_bid + 2))
            else: # Ample supply
                 return min(my_status['budget'], max(DAILY_SALARY * 0.4, avg_prev_bid + 1))

    # Strategy 4: No previous bids from opponents (e.g., Day 1 or new opponents)
    # Default strategy based on supply and my health
    if available_water_slots <= num_alive_opponents: # Supply is very tight
        if my_status['hp'] <= 3: # Desperate for water
            return min(my_status['budget'], DAILY_SALARY * 0.75)
        else: # Can afford to be slightly less aggressive
            return min(my_status['budget'], DAILY_SALARY * 0.6)
    else: # Supply is relatively abundant
        if my_status['hp'] <= 3: # Still need water, but less pressure
            return min(my_status['budget'], DAILY_SALARY * 0.5)
        else: # Healthy and abundant supply, bid conservatively
            return min(my_status['budget'], DAILY_SALARY * 0.4)

    # Fallback bid (should ideally be covered by previous conditions)
    return min(my_status['budget'], base_bid)

